// Writes src/abi.ts and src/launch/bytecode.ts from the Foundry artifacts in out/ (run `forge build` first). `pnpm gen:abi`.
import { mkdirSync, readFileSync, writeFileSync } from "node:fs";

const artifact = (name: string) => new URL(`../../../out/${name}.sol/${name}.json`, import.meta.url);

/** The text src/abi.ts must have to match the compiled contracts. */
export function renderAbiModule(): string {
  const abi = (name: string): unknown => (JSON.parse(readFileSync(artifact(name), "utf8")) as { abi: unknown }).abi;
  return [
    "// Generated by `pnpm gen:abi` from the Foundry artifacts in out/. Do not edit.",
    "",
    `export const proofkinAbi = ${JSON.stringify(abi("Proofkin"), null, 2)} as const;`,
    "",
    `export const rendererAbi = ${JSON.stringify(abi("Renderer"), null, 2)} as const;`,
    "",
  ].join("\n");
}

interface Artifact {
  bytecode: { object: string; linkReferences: Record<string, unknown> };
  deployedBytecode: {
    object: string;
    linkReferences: Record<string, unknown>;
    /** Absent when the contract has no immutables. */
    immutableReferences?: Record<string, { start: number; length: number }[]>;
  };
}

/**
 * The text src/launch/bytecode.ts must have to match the compiled contracts.
 * @dev The console deploys these bytes from a browser and then checks what the chain holds against them, so the file
 * only describes contracts it can handle: none needs a library linked, the renderer has no immutable, and the
 * collection's one immutable, the mint price, is a 32-byte word. A contract that changes any of that fails here, not
 * in front of the person deploying.
 */
export function renderLaunchModule(): string {
  const read = (name: string): Artifact => JSON.parse(readFileSync(artifact(name), "utf8")) as Artifact;
  const renderer = read("Renderer");
  const proofkin = read("Proofkin");

  for (const [name, a] of [["Renderer", renderer], ["Proofkin", proofkin]] as const) {
    if (Object.keys(a.bytecode.linkReferences).length + Object.keys(a.deployedBytecode.linkReferences).length > 0) {
      throw new Error(`${name} links a library, which the console cannot deploy`);
    }
    for (const code of [a.bytecode.object, a.deployedBytecode.object]) {
      if (!/^0x([0-9a-f]{2})+$/i.test(code)) throw new Error(`${name} has code that is not plain hex (is a library unlinked?)`);
    }
  }
  if (Object.keys(renderer.deployedBytecode.immutableReferences ?? {}).length > 0) {
    throw new Error("Renderer has an immutable, so a deployed one no longer holds exactly its compiled code");
  }
  const immutables = Object.values(proofkin.deployedBytecode.immutableReferences ?? {});
  if (immutables.length !== 1) {
    throw new Error(`Proofkin has ${immutables.length} immutables; the console knows to fill in one, the mint price`);
  }
  const places = immutables[0]!.toSorted((a, b) => a.start - b.start);
  if (places.some((place) => place.length !== 32)) throw new Error("the mint price is no longer a 32-byte word");

  return [
    "// Generated by `pnpm gen:abi` from the Foundry artifacts in out/. Do not edit.",
    'import type { Hex } from "viem";',
    "",
    "/** The code that deploys the renderer: sent in a transaction with no recipient. It takes no arguments. */",
    `export const rendererCreationCode: Hex = "${renderer.bytecode.object}";`,
    "",
    "/** What the renderer leaves on the chain. It has no immutables, so a deployed one holds exactly this. */",
    `export const rendererRuntimeCode: Hex = "${renderer.deployedBytecode.object}";`,
    "",
    "/** The code that deploys the collection; the constructor's ABI-encoded arguments (owner, renderer, price) follow it. */",
    `export const proofkinCreationCode: Hex = "${proofkin.bytecode.object}";`,
    "",
    "/** What the collection leaves on the chain, with an empty word wherever the compiler will put the mint price. */",
    `export const proofkinRuntimeCode: Hex = "${proofkin.deployedBytecode.object}";`,
    "",
    "/** Where those words are, in bytes from the start of the runtime code. */",
    `export const proofkinImmutables = ${JSON.stringify(places, null, 2)} as const;`,
    "",
  ].join("\n");
}

if (import.meta.main) {
  writeFileSync(new URL("../src/abi.ts", import.meta.url), renderAbiModule());
  mkdirSync(new URL("../src/launch/", import.meta.url), { recursive: true });
  writeFileSync(new URL("../src/launch/bytecode.ts", import.meta.url), renderLaunchModule());
  console.log("wrote src/abi.ts and src/launch/bytecode.ts");
}
